    var w=it.w,n=Math.max(2,Math.floor((w+12)/30)),tot=n*18+(n-1)*12,s='',i;
    for(i=0;i<n;i++)s+='<rect x="'+(-tot/2+i*30)+'" y="'+(-it.h/2)+'" width="18" height="'+it.h+'" rx="2" fill="'+WHITE+'" opacity=".96"/>';
